7: const PI = Math.PI;
8: const TAU = PI * 2;
9: const CYCLE = TAU * 2; // 720 crank degrees
10: 
11: const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
12: const lerp = (a, b, t) => a + (b - a) * t;
