14: function smoothLift(deg, open, close, maxLift) {
15:   // deg is 0..720, window may wrap (close > 720)
16:   let d = deg;
17:   if (d < open) d += 720;
18:   if (d < open || d > close) return 0;
19:   const u = (d - open) / (close - open);
20:   return maxLift * Math.sin(PI * u) ** 2;
21: }
22: 
23: function orificeFlow(pUp, pDn, tUp, area, cd = 0.68) {
24:   if (area <= 0 || pUp <= 0) return 0;
25:   const ratio = clamp(pDn / pUp, 0, 1);
26:   const g = 1.4;
27:   let term;
28:   if (ratio > 0.528) {
29:     term = Math.sqrt(Math.max(0, ratio ** (2 / g) - ratio ** ((g + 1) / g)));
30:   } else {
31:     term = Math.sqrt(Math.max(0, 0.528 ** (2 / g) - 0.528 ** ((g + 1) / g)));
32:   }
33:   // kg/s. The 0.684 factor folds the gamma constants in.
34:   return cd * area * (pUp / Math.sqrt(287 * tUp)) * 0.6845 * term * 3.4;
35: }
