37: export class Engine {
38:   constructor() {
39:     // --- hard parts (approximately a 449 cc single) ---
40:     this.bore = 0.084;
41:     this.stroke = 0.080;
42:     this.rod = 0.140;
43:     this.crankR = this.stroke / 2;
44:     this.pistonArea = (PI / 4) * this.bore ** 2;
45:     this.Vd = this.pistonArea * this.stroke;
46:     this.compression = 10.5;
47:     this.Vc = this.Vd / (this.compression - 1);
48:     this.inertia = 0.085; // crank + flywheel + dyno coupling, kg m^2
