57:     // valve geometry
58:     this.valveDia = 0.034;
59:     this.maxLift = 0.0105;
60:     this.ivo = 710; // 10 BTDC
61:     this.ivc = 940; // 40 ABDC (wraps)
62:     this.evo = 500; // 40 BBDC
63:     this.evc = 730; // 10 ATDC
