137:   volumeAt(theta) {
138:     const { crankR: a, rod: l, pistonArea: ap, Vc } = this;
139:     // pin distance below TDC
140:     const s = a + l - (a * Math.cos(theta) + Math.sqrt(l * l - (a * Math.sin(theta)) ** 2));
141:     return Vc + ap * s;
142:   }
143: 
144:   geometryAt(theta) {
145:     const { crankR: a, rod: l } = this;
146:     const sin = Math.sin(theta);
147:     const cos = Math.cos(theta);
148:     const root = Math.sqrt(l * l - (a * sin) ** 2);
149:     const pin = a * cos + root; // distance above crank centre
150:     const s = a + l - pin;
151:     const dPin = -a * sin - (a * a * sin * cos) / root;
152:     return { pin, s, dV: -this.pistonArea * dPin };
153:   }
154: 
155:   /* One physics tick. dt is real seconds. */
156:   step(dt) {
157:     const omegaAbs = Math.abs(this.omega);
158:     // Resolve crank angle finely enough for combustion, capped for cost.
159:     const hMax = omegaAbs > 8 ? Math.min(0.0012, 0.030 / omegaAbs) : 0.0012;
160:     let remaining = Math.min(dt, 0.05);
161:     let guard = 0;
162:     while (remaining > 1e-7 && guard < 900) {
163:       const h = Math.min(remaining, hMax);
164:       this.integrate(h);
165:       remaining -= h;
166:       guard++;
167:     }
168:     if (guard >= 900) this.omega *= 0.995;
169:   }
