171:   integrate(dt) {
172:     this.time += dt;
173:     this.stepCount++;
174:     const phase = ((this.theta / CYCLE) * 720) % 720;
175:     const prevPhase = (((this.theta - this.omega * dt) / CYCLE) * 720) % 720;
176:     const geo = this.geometryAt(this.theta);
177:     const V = this.volumeAt(this.theta);
178:     this.pistonPin = geo.pin;
179:     this.volume = V;
180:     this.dVdTheta = geo.dV;
181: 
182:     // ---------------- valves ----------------
183:     let iv = smoothLift(phase, this.ivo, this.ivc, this.maxLift);
184:     let ev = smoothLift(phase, this.evo, this.evc, this.maxLift);
185:     if (iv < 0.00005) iv = 0;
186:     if (ev < 0.00005) ev = 0;
187:     this.intakeLift = iv;
188:     this.exhaustLift = ev;
189: 
190:     // ---------------- gas pressure ----------------
191:     const R = 287;
192:     const cv = 718;
193:     const cp = 1005;
194:     const tCyl = clamp(this.temp, 240, 3600);
195:     let p = clamp((this.mass * R * tCyl) / Math.max(V, 1e-7), 1500, 2.4e7);
196: 
197:     // ---------------- manifold / throttle ----------------
198:     const areaThrottle = 0.5e-6 + 4.1e-4 * Math.pow(clamp(this.throttle, 0, 1), 2.2);
199:     let mdotThrottle = 0;
200:     if (this.pm < this.pAmb) mdotThrottle = orificeFlow(this.pAmb, this.pm, this.tAmb, areaThrottle);
201:     else mdotThrottle = -orificeFlow(this.pm, this.pAmb, tCyl, areaThrottle);
202:     // small idle air bleed so a closed plate still supports combustion
203:     const idleBleed = orificeFlow(this.pAmb, this.pm, this.tAmb, 3.5e-6);
204:     mdotThrottle += idleBleed;
205: 
206:     // intake charge. The valve curtain is large compared with the cylinder,
207:     // so cap each explicit step to a fraction of the mass needed to equalise.
208:     let dmIn = 0;
209:     let dmOut = 0;
210:     let intakeFlow = 0;
211:     if (iv > 0) {
212:       const area = PI * this.valveDia * iv * 0.86;
213:       const mdot = orificeFlow(this.pm, p, this.tAmb, area);
214:       const equil = ((this.pm - p) * V) / (R * ((tCyl + this.tAmb) * 0.5));
215:       if (mdot > 0) {
216:         dmIn = Math.min(mdot * dt, Math.max(0, equil) * 0.32);
217:         intakeFlow = dmIn / dt;
218:       } else {
219:         const rev = orificeFlow(p, this.pm, this.temp, area);
220:         dmOut = Math.min(rev * dt, Math.max(0, -equil) * 0.32);
221:         intakeFlow = -dmOut / dt;
222:         dmIn = -dmOut;
223:       }
224:     }
225: 
226:     let dmEx = 0;
227:     let exhaustFlow = 0;
228:     if (ev > 0) {
229:       const area = PI * this.valveDia * ev * 0.86;
230:       const mdot = orificeFlow(p, this.pe, this.temp, area);
231:       const equil = ((p - this.pe) * V) / (R * tCyl);
232:       if (mdot > 0) {
233:         dmEx = Math.min(mdot * dt, Math.max(0, equil) * 0.32);
234:         exhaustFlow = dmEx / dt;
235:       } else {
236:         const rev = orificeFlow(this.pe, p, 850, area);
237:         dmEx = -Math.min(rev * dt, Math.max(0, -equil) * 0.32);
238:       }
239:     }
240: 
241:     // plenum mass balance (small volume -> clamp for stability)
242:     const plenumMassRate = mdotThrottle - intakeFlow;
243:     this.pm += (plenumMassRate * R * this.tAmb * dt) / this.plenumV;
244:     this.pm = clamp(this.pm, 6000, this.pAmb * 1.03);
245:     if (this.pm > this.pAmb) this.pm = this.pAmb;
246:     this.lastThrottleFlow = mdotThrottle;
247:     this.lastIntakeFlow = intakeFlow;
248:     this.lastExhaustFlow = exhaustFlow;
249:     this.meterThrottle = (this.meterThrottle || 0) + mdotThrottle * dt;
250:     this.meterIntake = (this.meterIntake || 0) + intakeFlow * dt;
251:     this.meterExhaust = (this.meterExhaust || 0) + exhaustFlow * dt;
252:     // exhaust backpressure rises with flow, slight resonance
253:     this.pe = clamp(this.pAmb + 380 + Math.abs(exhaustFlow) * 2600, this.pAmb, this.pAmb + 9000);
254: 
255:     // ---------------- mass & energy exchange ----------------
256:     let dU = 0;
257:     if (dmIn > 0) {
258:       this.mass += dmIn;
259:       this.fuel += dmIn / this.afr;
260:       dU += cp * this.tAmb * dmIn;
261:       this.intakePulse = Math.min(1, this.intakePulse + dmIn * 2400);
262:     } else if (dmIn < 0) {
263:       const f = this.mass > 1e-9 ? Math.min(1, -dmIn / this.mass) : 0;
264:       this.mass = Math.max(0, this.mass + dmIn);
265:       this.fuel *= 1 - f;
266:       dU += cp * tCyl * dmIn;
267:     }
268:     if (dmEx > 0) {
269:       const f = this.mass > 1e-9 ? Math.min(1, dmEx / this.mass) : 0;
270:       this.mass = Math.max(0, this.mass - dmEx);
271:       this.fuel *= 1 - f;
272:       dU -= cp * tCyl * dmEx;
273:       this.exhaustPulse = Math.min(1, this.exhaustPulse + dmEx * 1700);
274:     } else if (dmEx < 0) {
275:       this.mass += -dmEx;
276:       dU += cp * 900 * -dmEx;
277:     }
278: 
279:     // ---------------- ignition & combustion ----------------
280:     const sparkAngle = (360 - this.advance + 720) % 720;
281:     let sparkNow = false;
282:     if (!this.sparkFired && this.fuel > 1e-9) {
283:       let crossed = false;
284:       if (phase >= prevPhase) crossed = sparkAngle > prevPhase && sparkAngle <= phase;
285:       else crossed = sparkAngle > prevPhase || sparkAngle <= phase;
286:       // at very low cranking speed allow a small timing nudge
287:       if (crossed || (this.omega < 15 && Math.abs(phase - sparkAngle) < 1.2)) {
288:         sparkNow = true;
289:       }
290:     }
291:     if (sparkNow) {
292:       this.sparkFired = true;
293:       this.sparkPulse = 1;
294:       this.burning = true;
295:       this.burnStart = phase;
296:       this.burned = 0;
297:       this.availableFuel = Math.max(0, this.fuel);
298:       this.cycleFuel = this.availableFuel;
299:       this.knock = 0;
300:     }
301: 
302:     let qComb = 0;
303:     if (this.burning && this.availableFuel > 0) {
304:       let elapsed = phase - this.burnStart;
305:       if (elapsed < -360) elapsed += 720;
306:       if (elapsed < 0) elapsed = 0;
307:       const u = clamp(elapsed / this.burnDuration, 0, 1);
308:       const xb = u >= 1 ? 1 : 1 - Math.exp(-6.9 * Math.pow(u, 2.1));
309:       const dx = Math.max(0, xb - this.burned);
310:       if (dx > 0) {
311:         // cold combustion is incomplete and late; mixture strength matters
312:         const warm = clamp((this.wallC - 24) / 70, 0, 1);
313:         const strength = clamp((this.availableFuel / Math.max(this.mass, 1e-9)) * this.afr, 0, 1.1);
314:         const eff = (0.58 + 0.33 * warm) * clamp(strength, 0.25, 1);
315:         const dQ = this.availableFuel * dx * this.fuelLhv * eff;
316:         qComb += dQ;
317:         this.burned += dx;
318:         this.fuel = Math.max(0, this.fuel - this.availableFuel * dx);
319:         this.combustion = Math.min(1, this.combustion + dx * 2.4);
320:       }
321:       if (u >= 1) {
322:         this.burning = false;
323:         if (this.burned < 0.6) this.lastEvent = 'MISFIRE';
324:       }
325:     }
326: 
327:     // heat release raises internal energy
328:     dU += qComb;
329: 
330:     // wall heat transfer, Woschni-ish (calibrated for a small single)
331:     const area = 0.022 + this.pistonArea;
332:     const hConv = 130 + 0.00009 * p;
333:     const dQwall = hConv * area * (tCyl - (this.wallC + 273.15)) * dt;
334:     dU -= dQwall;
335: 
336:     // first law: dU = dQ - p dV  (volume work)
337:     dU -= p * geo.dV * this.omega * dt;
338:     this.temp += dU / Math.max(this.mass * cv, 1e-7);
339:     this.temp = clamp(this.temp, 250, 3400);
340: 
341:     // wall / coolant thermal inertia
342:     const qIntoWall = dQwall;
343:     const qCool = 420 * (this.wallC - (this.tCoolant - 273.15));
344:     this.wallC += ((qIntoWall - qCool) / 6000) * dt;
345:     this.wallC = clamp(this.wallC, 15, 190);
346:     this.oilC += ((this.wallC - this.oilC) * 0.12 - 0.015 * (this.oilC - 45)) * dt * 0.25;
347: 
348:     this.pressure = clamp((Math.max(this.mass, 1e-7) * R * this.temp) / Math.max(V, 1e-7), 1500, 2.6e7);
349: 
350:     // ---------------- knock ----------------
351:     const loadFrac = clamp((this.pm - 28000) / 72000, 0, 1);
352:     const heatFrac = clamp((this.wallC - 80) / 55, 0, 1.4);
353:     this.knockLimit = 35 - 13 * loadFrac - 5 * heatFrac - 2.4 * clamp(this.omega / 700, 0, 1);
354:     let knockTarget = 0;
355:     if (this.burning && this.availableFuel > 0 && qComb > 0) {
356:       const over = this.advance - this.knockLimit;
357:       if (over > 0) {
358:         const peak = clamp(p / 4.2e6, 0.15, 1.25);
359:         knockTarget = clamp(over / 11, 0, 1) * peak;
360:       }
361:     }
362:     this.knockTarget = Math.max(knockTarget, this.knockTarget * Math.exp(-dt * 1.6));
363:     this.knockMeter += (this.knockTarget - this.knockMeter) * Math.min(1, dt * 6);
364:     this.knock = this.knockMeter;
365:     if (this.knockTarget > 0.25) {
366:       this.knockEvents++;
367:       this.detonation = Math.min(1, this.knockTarget + 0.35);
368:       this.lastEvent = 'DETONATION';
369:     }
370: 
371:     // ---------------- torque ----------------
372:     this.tInd = (p - this.pAmb) * geo.dV * (1 - 0.12 * this.knockMeter);
373:     const w = this.omega;
374:     const rpmNow = (w * 60) / TAU;
375:     this.tFric = 1.35 + 0.0055 * w + 0.0000068 * w * w;
376:     if (rpmNow > 6900) this.tFric += (rpmNow - 6900) * 0.02;
377:     if (w < 0.35) this.tFric *= 1.9;
378:     this.tLoad = (this.load / 100) * (1.2 + 0.062 * w) * 1.15;
379:     this.tStarter = 0;
380:     if (this.starter && w < 72) {
381:       this.tStarter = 52 * clamp(1 - w / 78, 0, 1);
382:       this.cranking = true;
383:     } else this.cranking = false;
384: 
385:     let net = this.tInd - this.tFric - this.tLoad + this.tStarter;
386:     if (this.loading) net -= this.loading;
387:     this.tNet = net;
388:     this.omega += (net / this.inertia) * dt;
389:     if (this.omega < 0) this.omega = 0;
390:     if (this.omega < 0.4 && this.tStarter <= 0.1 && net < 0.5) this.omega = 0;
391: 
392:     this.theta += this.omega * dt;
393:     if (this.theta >= CYCLE) {
394:       this.theta -= CYCLE;
395:       this.cycleIndex++;
396:       this.sparkFired = false;
397:       this.burning = false;
398:       this.burned = 0;
399:       this.availableFuel = Math.max(0, this.fuel);
400:       this.cycleFuel = this.availableFuel;
401:       this.totalCycles++;
402:       this.knock = 0;
403:       if (this.availableFuel > 0 && this.omega > 2) {
404:         this.burnDuration = lerp(76, 56, clamp(this.omega / 550, 0, 1));
405:       }
406:     }
407: 
408:     // measured output (averaged over a few cycles for a readable gauge)
409:     const instTorque = Math.max(0, this.tInd - this.tFric);
410:     const alpha = 1 - Math.exp(-dt / 0.55);
411:     this.torqueAvg = (this.torqueAvg ?? 0) + (instTorque - (this.torqueAvg ?? 0)) * alpha;
412:     this.torque = this.torqueAvg;
413:     this.powerKW = (this.torqueAvg * this.omega) / 1000;
414:     const rpm = (this.omega * 60) / TAU;
415:     if (rpm > 400) {
416:       this.peakRpm = Math.max(this.peakRpm, rpm);
417:       this.peakTorque = Math.max(this.peakTorque, this.torqueAvg);
418:       this.peakPower = Math.max(this.peakPower, this.powerKW * 1.34102);
419:       this.running = true;
420:     }
421:     if (rpm < 120) this.running = false;
422: 
423:     // ---------------- damage ----------------
424:     this.detonation = Math.max(0, this.detonation - dt * 5);
425:     this.combustion = Math.max(0, this.combustion - dt * 5);
426:     this.sparkPulse = Math.max(0, this.sparkPulse - dt * 22);
427:     this.exhaustPulse *= Math.exp(-dt * 9);
428:     this.intakePulse *= Math.exp(-dt * 9);
429:     this.eventTimer = Math.max(0, this.eventTimer - dt);
430: 
431:     if (rpm > 7250) {
432:       this.overRev = Math.min(1, this.overRev + dt * 2);
433:       this.health -= ((rpm - 7250) / 800) * 1.9 * dt;
434:     } else {
435:       this.overRev = Math.max(0, this.overRev - dt * 3);
436:     }
437:     if (this.wallC > 116) this.health -= (this.wallC - 116) * 0.12 * dt;
438:     if (this.knock > 0.22) this.health -= (this.knock - 0.2) * 5.5 * dt;
439:     this.health = clamp(this.health, 0, 100);
440: 
441:     if (this.health <= 0) {
442:       this.omega = 0;
443:       this.stalled = true;
444:       this.running = false;
445:       this.lastEvent = 'SEIZED';
446:     }
447:     if (this.omega < 0.4 && !this.starter) this.stalled = true;
448:     if (this.omega > 8) this.stalled = false;
449:   }
450: }
