452: function cam(phase) {
453:   // combustion lives around TDC; bell curve in crank degrees
454:   let d = phase - 360;
455:   if (d > 180) d -= 720;
456:   if (d < -180) d += 720;
457:   return Math.exp(-(d * d) / (2 * 38 * 38));
458: }
