497:     `<div class="result-stat"><span>${k}</span><b>${v}</b><small>${u}</small></div>`).join('');
498: 
499:   $('resultCash').textContent = success ? `+$${reward.toLocaleString()}` : '$0';
500:   $('nextBtn').classList.toggle('hidden', !success);
501:   $('retryBtn').classList.remove('hidden');
