675: function updateDemo(dt) {
676:   demoT += dt;
677:   if (!demoCaught) {
678:     demo.starter = true;
679:     demo.step(dt);
680:     if (rpmOf(demo) > 900) {
681:       demoCaught = true;
682:       demo.starter = false;
683:     }
684:   } else {
685:     const blip = Math.max(0, Math.sin(demoT * 0.42)) ** 12;
686:     demo.throttle = 0.055 + blip * 0.12;
687:     demo.load = 0;
688:     demo.step(dt);
689:   }
690:   if (rpmOf(demo) < 350) {
691:     demoCaught = false;
692:     demo.starter = true;
693:   }
694: }
