696: function updateGame(dt) {
697:   // analog keyboard trims
698:   let dThr = 0;
699:   let dAdv = 0;
700:   let dLoad = 0;
701:   if (keys.has('KeyW') || keys.has('ArrowUp')) dThr += 46;
702:   if (keys.has('KeyS') || keys.has('ArrowDown')) dThr -= 46;
703:   if (keys.has('KeyA') || keys.has('ArrowLeft')) dAdv -= 16;
704:   if (keys.has('KeyD') || keys.has('ArrowRight')) dAdv += 16;
705:   if (keys.has('KeyQ')) dLoad -= 38;
706:   if (keys.has('KeyE')) dLoad += 38;
707:   if (dThr) setControl('throttle', game.control.throttle + dThr * dt);
708:   if (dAdv) setControl('advance', game.control.advance + dAdv * dt);
709:   if (dLoad) setControl('load', game.control.load + dLoad * dt);
710: 
711:   game.time += dt;
712: 
713:   engine.throttle = game.control.throttle / 100;
714:   engine.advance = game.control.advance;
715:   engine.load = game.control.load;
716: 
717:   // automatic starter until first catch, then hand control back
718:   if (!game.hasCaught) {
719:     game.autoCrank -= dt;
720:     engine.starter = game.autoCrank > 0 || starterHeld || starterKey;
721:   } else {
722:     engine.starter = starterHeld || starterKey;
723:   }
724: 
725:   engine.step(dt);
726:   const rpm = rpmOf(engine);
727:   if (rpm > game.peakRpm) game.peakRpm = rpm;
728:   if (engine.powerKW > game.peakKW) game.peakKW = engine.powerKW;
729:   if (engine.torque > game.peakTorque) game.peakTorque = engine.torque;
730: 
731:   if (!game.hasCaught && rpm > 780) {
732:     game.hasCaught = true;
733:     game.started = true;
734:     game.autoCrank = 0;
735:     setCoach(game.stage.coach);
736:   }
737:   if (!game.started && rpm > 780) game.started = true;
738: 
739:   // stall awareness
740:   if (game.started && rpm < 260 && !engine.starter) {
741:     game.stalledFor += dt;
742:   } else {
743:     game.stalledFor = 0;
744:   }
745:   if (game.stalledFor > 2.5 && !stallWarned) {
746:     stallWarned = true;
747:     showToast('STALLED', 'bad', 1.2);
748:     setCoach('engine stalled — hold ignition to re-crank');
749:   }
750:   if (rpm > 700) stallWarned = false;
751: 
752:   // event toasts
753:   if (engine.knock > 0.22 && knockWas <= 0.22) showToast('DETONATION', 'bad', 1.05);
754:   knockWas = engine.knock;
755:   if (engine.wallC > 108 && !heatWarned) {
756:     heatWarned = true;
757:     showToast('COOLANT CRITICAL', 'bad', 1.3);
758:   }
759:   if (engine.wallC < 104) heatWarned = false;
760:   if (engine.lastEvent === 'MISFIRE' && engine.eventTimer <= 0) {
761:     // engine raises this once per cycle; don't spam the toast
762:   }
763: 
764:   // conditions and hold
765:   let ok = game.started;
766:   game.stage.conds.forEach((c, i) => {
767:     const pass = c.test(engine);
768:     if (!pass) ok = false;
769:     game.condEls[i]?.classList.toggle('ok', pass);
770:   });
771: 
772:   if (ok) game.hold += dt;
773:   else game.hold = Math.max(0, game.hold - dt * 1.4);
774: 
775:   const prog = clamp(game.hold / game.stage.hold, 0, 1);
776:   $('progressFill').style.width = (prog * 100).toFixed(1) + '%';
777:   $('progressLabel').textContent = `${game.hold.toFixed(1)} / ${game.stage.hold.toFixed(1)} s`;
778: 
779:   const status = $('testStatus');
780:   if (ok) {
781:     status.textContent = 'HOLDING';
782:     status.className = 'live';
783:   } else {
784:     status.textContent = 'LIVE';
785:     status.className = 'live' + (engine.knock > 0.22 || engine.wallC > 108 ? ' warn' : '');
786:   }
787: 
788:   if (game.hold >= game.stage.hold) {
789:     finishStage(true);
790:     return;
791:   }
792:   if (engine.health <= 0.2) {
793:     finishStage(false, 'SEIZED');
794:     return;
795:   }
796:   if (game.time >= game.stage.timeLimit) {
797:     finishStage(false, 'TIME');
798:     return;
799:   }
800: 
801:   if (toastTimer > 0) {
802:     toastTimer -= dt;
803:     if (toastTimer <= 0) $('toast').classList.remove('show');
804:   }
805: }
