879: /* ------------------------------------------------------------------ */
880: /* Tachometer                                                          */
881: /* ------------------------------------------------------------------ */
882: let tachStatic = null;
883: let tachStaticDpr = 0;
884: 
885: function buildTachStatic(dpr) {
886:   const c = document.createElement('canvas');
887:   c.width = Math.round(560 * dpr);
888:   c.height = Math.round(310 * dpr);
889:   const ctx = c.getContext('2d');
890:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
891:   const cx = 280;
892:   const cy = 255;
893:   const r = 192;
894:   const a0 = Math.PI * 0.75;
895:   const a1 = Math.PI * 2.25;
896:   const toAngle = (v) => a0 + (v / 8000) * (a1 - a0);
897: 
898:   // bezel
899:   const bez = ctx.createRadialGradient(cx - 40, cy - 70, 20, cx, cy, 220);
900:   bez.addColorStop(0, 'rgba(40,54,64,0.8)');
901:   bez.addColorStop(0.72, 'rgba(12,18,23,0.9)');
902:   bez.addColorStop(1, 'rgba(5,8,10,0.95)');
903:   ctx.fillStyle = bez;
904:   ctx.beginPath();
905:   ctx.arc(cx, cy, 214, Math.PI, Math.PI * 2);
906:   ctx.lineTo(cx + 214, cy);
907:   ctx.arc(cx, cy, 214, 0, Math.PI);
908:   ctx.fill();
909: 
910:   // arc bed and redline
911:   ctx.strokeStyle = 'rgba(130,160,180,0.13)';
912:   ctx.lineWidth = 12;
913:   ctx.beginPath();
914:   ctx.arc(cx, cy, r, a0, a1);
915:   ctx.stroke();
916:   ctx.strokeStyle = 'rgba(255,90,69,0.35)';
917:   ctx.beginPath();
918:   ctx.arc(cx, cy, r, toAngle(7000), a1);
919:   ctx.stroke();
920: 
921:   // ticks / numerals
922:   for (let i = 0; i <= 32; i++) {
923:     const v = i * 250;
924:     const a = toAngle(v);
925:     const major = i % 4 === 0;
926:     const inner = r - (major ? 22 : 10);
927:     ctx.strokeStyle = major
928:       ? v >= 7000 ? 'rgba(255,90,69,0.9)' : 'rgba(215,228,236,0.75)'
929:       : 'rgba(150,175,190,0.35)';
930:     ctx.lineWidth = major ? 2 : 1;
931:     ctx.beginPath();
932:     ctx.moveTo(cx + Math.cos(a) * inner, cy + Math.sin(a) * inner);
933:     ctx.lineTo(cx + Math.cos(a) * (r - 4), cy + Math.sin(a) * (r - 4));
934:     ctx.stroke();
935:     if (major) {
936:       const lr = r - 45;
937:       ctx.fillStyle = v >= 7000 ? 'rgba(255,120,100,0.85)' : 'rgba(190,208,220,0.68)';
938:       ctx.font = '600 13px "SFMono-Regular", "Courier New", monospace';
939:       ctx.textAlign = 'center';
940:       ctx.textBaseline = 'middle';
941:       ctx.fillText(String(v / 1000), cx + Math.cos(a) * lr, cy + Math.sin(a) * lr);
942:     }
943:   }
944:   ctx.fillStyle = 'rgba(140,165,180,0.35)';
945:   ctx.font = '700 8px "SFMono-Regular", monospace';
946:   ctx.textAlign = 'center';
947:   ctx.fillText('RPM ×1000', cx, cy - 58);
948:   ctx.fillStyle = 'rgba(120,145,160,0.28)';
949:   ctx.font = '600 7px "SFMono-Regular", monospace';
950:   ctx.fillText('SC-1 DYNO MULE', cx, cy - 45);
951:   ctx.textAlign = 'left';
952:   return c;
953: }
954: 
955: function drawTach(e) {
956:   const dpr = Math.min(window.devicePixelRatio || 1, 2);
957:   if (!tachStatic || tachStaticDpr !== dpr) {
958:     tachStatic = buildTachStatic(dpr);
959:     tachStaticDpr = dpr;
960:   }
961:   if (tachCanvas.width !== tachStatic.width || tachCanvas.height !== tachStatic.height) {
962:     tachCanvas.width = tachStatic.width;
963:     tachCanvas.height = tachStatic.height;
964:   }
965:   const ctx = tachCtx;
966:   ctx.setTransform(1, 0, 0, 1, 0, 0);
967:   ctx.clearRect(0, 0, tachCanvas.width, tachCanvas.height);
968:   ctx.drawImage(tachStatic, 0, 0);
969:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
970:   const cx = 280;
971:   const cy = 255;
972:   const r = 192;
973:   const a0 = Math.PI * 0.75;
974:   const a1 = Math.PI * 2.25;
975:   const rpm = clamp(rpmOf(e), 0, 8000);
976:   const toAngle = (v) => a0 + (v / 8000) * (a1 - a0);
977: 
978:   // target band for the active test
979:   if (phase === 'running') {
980:     const rc = game.stage.conds.find((c) => c.label.startsWith('RPM'));
981:     if (rc) {
982:       const m = rc.label.match(/(\d+)[^\d]+(\d+)/);
983:       if (m) {
984:         ctx.strokeStyle = 'rgba(107,219,155,0.55)';
985:         ctx.lineWidth = 9;
986:         ctx.beginPath();
987:         ctx.arc(cx, cy, r, toAngle(Number(m[1])), toAngle(Number(m[2])));
988:         ctx.stroke();
989:       }
990:     }
991:   }
992: 
993:   // active arc: layered strokes instead of a costly shadow blur
