cat > /tmp/opencode/flow2.mjs <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
const browser = await chromium.launch({...config.browser.launchOptions, timeout:30000});
const page = await browser.newPage({viewport:{width:1280,height:800}});
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.error('PAGEERROR', e.message); });
const log = (...a) => console.log(...a);
const state = () => page.evaluate(() => {
  const sc = window.__sc;
  return {
    phase: sc.game.paused ? (document.getElementById('resultScreen').classList.contains('hidden') ? (document.getElementById('garageScreen').classList.contains('hidden') ? 'running-paused' : 'garage') : 'result') : 'running',
    stage: sc.game.stageIndex,
    cash: sc.save.cash,
    medals: {...sc.save.medals},
    unlocked: sc.save.unlocked,
    time: +sc.game.time.toFixed(1),
    rpm: Math.round(sc.engine.omega*60/(Math.PI*2)),
    mods: {...sc.engine.mods},
    resultTitle: document.getElementById('resultTitle').textContent,
    medal: document.querySelector('#resultMedal').className,
    resultCash: document.getElementById('resultCash').textContent,
    nextHidden: document.getElementById('nextBtn').classList.contains('hidden'),
    retryText: document.getElementById('retryBtn').textContent,
    store: localStorage.getItem('single-cylinder-career.v1')
  };
});

await page.goto('http://localhost:3002', {waitUntil:'load', timeout:45000});
await page.evaluate(() => localStorage.removeItem('single-cylinder-career.v1'));
await page.reload({waitUntil:'load'});
await page.waitForTimeout(300);

// frame rate sanity
const fps = await page.evaluate(() => new Promise(res => {
  let n=0; const t0=performance.now();
  function tick(){ n++; if(performance.now()-t0 > 1000) res(n); else requestAnimationFrame(tick); }
  requestAnimationFrame(tick);
}));
log('FPS ~', fps);

await page.click('#startBtn');
await page.waitForTimeout(600);
log('START', await state());

const pars = [14,25,27,28,55,26];
const rewards = [900,1300,1700,1900,2300,2800];
for (let i=0;i<6;i++) {
  const st = await state();
  if (i>0) {
    // previous finish should have left result screen; click next
    await page.click('#nextBtn');
    await page.waitForTimeout(250);
    log(`OPEN ${i+1}`, await state());
  }
  await page.evaluate(({i,par}) => {
    const sc = window.__sc;
    sc.game.time = par;
    sc.game.peakKW = 18 + i;
    sc.game.peakTorque = 25 + i;
    sc.engine.health = 95;
    sc.finishStage(true);
  }, {i, par: pars[i]});
  await page.waitForTimeout(150);
  const res = await state();
  log(`FINISH ${i+1}`, res);
  if (!res.medal.includes('gold')) throw new Error('expected gold on stage '+(i+1));
}
// final next -> garage
await page.click('#nextBtn');
await page.waitForTimeout(300);
const garage = await page.evaluate(() => ({
  visible: !document.getElementById('garageScreen').classList.contains('hidden'),
  cash: document.getElementById('garageCash').textContent,
  badges: [...document.querySelectorAll('.stage-item .badge')].map(e=>e.textContent),
  locked: [...document.querySelectorAll('.stage-item')].filter(e=>e.disabled).length,
  nextBtnText: document.getElementById('nextBtn').textContent
}));
log('GARAGE AFTER CAMPAIGN', garage);

// buy port upgrade
const buy = await page.evaluate(() => {
  const items = [...document.querySelectorAll('.shop-item')];
  const port = items.find(el => el.textContent.includes('PORT & POLISH'));
  port.querySelector('button').click();
  const sc = window.__sc;
  return { cash: sc.save.cash, upgrades: {...sc.save.upgrades}, cashText: document.getElementById('garageCash').textContent, hint: document.getElementById('garageHint').textContent, btn: port.querySelector('button').textContent };
});
log('BUY PORT', buy);

// launch stage 1 from garage, verify mod applied
await page.click('#launchBtn');
await page.waitForTimeout(400);
log('LAUNCH W/ MODS', await state());

// fail path
await page.evaluate(() => { window.__sc.finishStage(false, 'SEIZED'); });
await page.waitForTimeout(150);
log('FAIL', await state());
const beforeCash = await page.evaluate(()=>window.__sc.save.cash);
await page.click('#retryBtn');
await page.waitForTimeout(300);
log('RETRY', await state());
const afterCash = await page.evaluate(()=>window.__sc.save.cash);
log('CASH UNCHANGED ON FAIL/RETRY', beforeCash === afterCash);

// keyboard controls
await page.keyboard.down('KeyW');
await page.waitForTimeout(700);
await page.keyboard.up('KeyW');
await page.keyboard.down('KeyD');
await page.waitForTimeout(500);
await page.keyboard.up('KeyD');
await page.keyboard.down('KeyE');
await page.waitForTimeout(500);
await page.keyboard.up('KeyE');
await page.keyboard.down('Space');
await page.waitForTimeout(200);
const spaceActive = await page.evaluate(()=>document.getElementById('starterBtn').classList.contains('active'));
await page.keyboard.up('Space');
await page.keyboard.press('KeyM');
await page.waitForTimeout(120);
const kb = await page.evaluate(() => ({
  throttle: document.getElementById('throttle').value,
  advance: document.getElementById('advance').value,
  load: document.getElementById('load').value,
  throttleOut: document.getElementById('throttleVal').textContent,
  sound: document.getElementById('soundBtn').textContent,
  spaceActive: document.getElementById('starterBtn').classList.contains('active'),
  starterHeld: window.__sc.game ? undefined : undefined
}));
log('KEYBOARD', {spaceActiveDuringHold: spaceActive, ...kb});

// escape opens garage while running
await page.keyboard.press('Escape');
await page.waitForTimeout(250);
log('ESC GARAGE', await page.evaluate(()=>({
  garage: !document.getElementById('garageScreen').classList.contains('hidden'),
  cash: document.getElementById('garageCash').textContent,
  port: [...document.querySelectorAll('.shop-item')].find(e=>e.textContent.includes('PORT & POLISH')).querySelector('button').textContent
})));

// persistence reload
await page.reload({waitUntil:'load'});
await page.waitForTimeout(400);
const persisted = await page.evaluate(() => {
  const raw = JSON.parse(localStorage.getItem('single-cylinder-career.v1'));
  return { save: raw, titleSave: document.getElementById('titleSave').textContent, titleVisible: !document.getElementById('titleScreen').classList.contains('hidden') };
});
log('PERSISTED', persisted);

log('ERRORS', errors);
await browser.close();
EOF
