265:   drawDyno(ctx, e, dt) {
266:     const load = clamp((e.load || 0) / 100, 0, 1);
267:     const hot = clamp(load * 0.9 + Math.max(0, (e.wallC - 70) / 60), 0, 1);
268:     this.beltPhase += dt * (2 + (e.omega || 0) * 1.5);
269:     const fx = CX + CRANK_R * Math.sin(e.theta);
270:     const fy = CY - CRANK_R * Math.cos(e.theta);
271: 
272:     // belt loop behind the flywheel
273:     const d = Math.hypot(DYNO.x - CX, DYNO.y - CY);
274:     const a1 = Math.atan2(DYNO.y - CY, DYNO.x - CX);
275:     const r1 = FLY_R + 10;
276:     const r2 = DYNO.r + 10;
277:     const off = Math.acos(clamp((r1 - r2) / d, -1, 1));
278:     const p1 = [CX + r1 * Math.cos(a1 + off), CY + r1 * Math.sin(a1 + off)];
279:     const p2 = [DYNO.x + r2 * Math.cos(a1 + off), DYNO.y + r2 * Math.sin(a1 + off)];
280:     const p3 = [DYNO.x + r2 * Math.cos(a1 - off), DYNO.y + r2 * Math.sin(a1 - off)];
281:     const p4 = [CX + r1 * Math.cos(a1 - off), CY + r1 * Math.sin(a1 - off)];
282:     ctx.save();
283:     ctx.lineCap = 'round';
284:     ctx.strokeStyle = '#111417';
285:     ctx.lineWidth = 20;
286:     ctx.beginPath();
287:     ctx.moveTo(p1[0], p1[1]);
288:     ctx.lineTo(p2[0], p2[1]);
289:     ctx.stroke();
290:     ctx.beginPath();
291:     ctx.moveTo(p4[0], p4[1]);
292:     ctx.lineTo(p3[0], p3[1]);
293:     ctx.stroke();
294:     ctx.strokeStyle = '#2d3338';
295:     ctx.lineWidth = 12;
296:     ctx.stroke();
297:     ctx.beginPath();
298:     ctx.arc(CX, CY, r1, a1 + off, a1 - off + TAU);
299:     ctx.arc(DYNO.x, DYNO.y, r2, a1 - off, a1 + off);
300:     ctx.closePath();
301:     ctx.strokeStyle = '#23282c';
302:     ctx.lineWidth = 8;
303:     ctx.stroke();
304:     // belt cleats
305:     ctx.strokeStyle = 'rgba(190,200,208,0.25)';
306:     ctx.lineWidth = 2;
307:     for (let i = 0; i < 22; i++) {
308:       const a = (i / 22) * TAU + this.beltPhase * 0.08;
309:       const x = CX + r1 * Math.cos(a);
310:       const y = CY + r1 * Math.sin(a);
311:       ctx.beginPath();
312:       ctx.moveTo(x, y);
313:       ctx.lineTo(x + Math.cos(a) * 10, y + Math.sin(a) * 10);
314:       ctx.stroke();
315:     }
316:     ctx.restore();
317: 
318:     // dyno chassis
319:     ctx.save();
320:     const chassis = linear(ctx, 1020, 690, 1280, 890, [
321:       [0, '#1a2026'], [0.3, '#3a444c'], [0.6, '#1b2126'], [1, '#080a0c'],
322:     ]);
323:     ctx.fillStyle = chassis;
324:     rr(ctx, 1010, 688, 268, 200, 22);
325:     ctx.fill();
326:     ctx.strokeStyle = '#050607';
327:     ctx.lineWidth = 4;
328:     ctx.stroke();
329:     // cooling slots
330:     ctx.strokeStyle = 'rgba(0,0,0,0.55)';
331:     ctx.lineWidth = 3;
332:     for (let i = 0; i < 7; i++) {
333:       ctx.beginPath();
334:       ctx.moveTo(1040, 712 + i * 13);
335:       ctx.lineTo(1105, 712 + i * 13);
336:       ctx.stroke();
337:     }
338:     // warning label
339:     ctx.fillStyle = '#c9a24a';
340:     ctx.font = '700 11px "Arial Narrow", sans-serif';
341:     ctx.letterSpacing = '1px';
342:     ctx.fillText('DYNO BRAKE', 1042, 858);
343:     ctx.fillStyle = '#8b99a4';
344:     ctx.font = '600 9px "Arial Narrow", sans-serif';
345:     ctx.fillText('WATER-COOLED / 30 kW', 1042, 873);
346:     ctx.restore();
347: 
348:     // rotor
349:     ctx.save();
350:     ctx.translate(DYNO.x, DYNO.y);
351:     ctx.rotate(e.theta * 0.6);
352:     const rotor = radial(ctx, -18, -18, 4, 86, [
353:       [0, '#c8d2da'], [0.2, '#68747e'], [0.55, '#252c32'], [0.85, '#59656f'], [1, '#101417'],
354:     ]);
355:     ctx.fillStyle = rotor;
356:     ctx.beginPath();
357:     ctx.arc(0, 0, DYNO.r, 0, TAU);
358:     ctx.fill();
359:     ctx.strokeStyle = '#0a0c0e';
360:     ctx.lineWidth = 4;
361:     ctx.stroke();
362:     ctx.fillStyle = '#0b0e11';
363:     for (let i = 0; i < 6; i++) {
364:       const a = (i / 6) * TAU;
365:       ctx.beginPath();
366:       ctx.arc(Math.cos(a) * 45, Math.sin(a) * 45, 10, 0, TAU);
367:       ctx.fill();
368:     }
369:     ctx.strokeStyle = 'rgba(255,255,255,0.12)';
370:     ctx.lineWidth = 1.5;
371:     for (let i = 0; i < 12; i++) {
372:       const a = (i / 12) * TAU;
373:       ctx.beginPath();
374:       ctx.moveTo(Math.cos(a) * 55, Math.sin(a) * 55);
375:       ctx.lineTo(Math.cos(a) * 78, Math.sin(a) * 78);
376:       ctx.stroke();
377:     }
378:     ctx.restore();
379: 
380:     if (hot > 0.02) {
381:       const halo = radial(ctx, DYNO.x, DYNO.y, DYNO.r * 0.55, DYNO.r * 1.7, [
382:         [0, `rgba(255,120,40,${0.22 * hot})`],
383:         [0.5, `rgba(255,70,20,${0.08 * hot})`],
384:         [1, 'rgba(0,0,0,0)'],
385:       ]);
386:       ctx.fillStyle = halo;
387:       ctx.beginPath();
388:       ctx.arc(DYNO.x, DYNO.y, DYNO.r * 1.7, 0, TAU);
389:       ctx.fill();
390:     }
391:   }
