393:   /* ------------------------------------------------------------------ */
394:   drawCrankAndFlywheel(ctx, e) {
395:     // flywheel
396:     ctx.save();
397:     ctx.translate(CX, CY);
398:     ctx.rotate(e.theta);
399:     const fw = radial(ctx, -40, -40, 10, FLY_R + 4, [
400:       [0, '#3c444b'], [0.45, '#232a30'], [0.8, '#4a545d'], [1, '#0a0d0f'],
401:     ]);
402:     ctx.fillStyle = fw;
403:     ctx.beginPath();
404:     ctx.arc(0, 0, FLY_R, 0, TAU);
405:     ctx.fill();
406:     ctx.strokeStyle = '#06080a';
407:     ctx.lineWidth = 7;
408:     ctx.stroke();
409:     // ring gear teeth
410:     ctx.fillStyle = '#20262b';
411:     for (let i = 0; i < 54; i++) {
412:       const a = (i / 54) * TAU;
413:       ctx.save();
414:       ctx.rotate(a);
415:       ctx.fillRect(FLY_R - 4, -6, 18, 12);
416:       ctx.restore();
417:     }
418:     ctx.strokeStyle = 'rgba(210,220,228,0.16)';
419:     ctx.lineWidth = 2;
420:     ctx.beginPath();
421:     ctx.arc(0, 0, FLY_R - 22, 0, TAU);
422:     ctx.stroke();
423:     // lightening holes
424:     ctx.fillStyle = '#070a0c';
425:     for (let i = 0; i < 6; i++) {
426:       const a = (i / 6) * TAU;
427:       ctx.beginPath();
428:       ctx.ellipse(Math.cos(a) * 104, Math.sin(a) * 104, 23, 15, a, 0, TAU);
429:       ctx.fill();
430:     }
431:     ctx.fillStyle = '#12171b';
432:     ctx.beginPath();
433:     ctx.arc(0, 0, 34, 0, TAU);
434:     ctx.fill();
435:     ctx.strokeStyle = 'rgba(210,220,228,0.25)';
436:     ctx.stroke();
437:     ctx.restore();
438: 
439:     // crankcase shell
440:     const caseGrad = linear(ctx, 540, 530, 900, 810, [
441:       [0, '#0b0e11'], [0.2, '#303840'], [0.36, '#79848d'], [0.5, '#4f5962'], [0.68, '#1b2126'], [1, '#07090b'],
442:     ]);
443:     ctx.fillStyle = caseGrad;
444:     ctx.beginPath();
445:     ctx.moveTo(552, 532);
446:     ctx.lineTo(888, 532);
447:     ctx.bezierCurveTo(928, 610, 918, 738, 822, 792);
448:     ctx.bezierCurveTo(768, 822, 672, 822, 618, 792);
449:     ctx.bezierCurveTo(525, 736, 514, 610, 552, 532);
450:     ctx.closePath();
451:     ctx.fill();
452:     ctx.strokeStyle = '#050708';
453:     ctx.lineWidth = 5;
454:     ctx.stroke();
455: 
456:     // cut-away crank cavity
457:     const cavity = radial(ctx, CX, CY, 30, 235, [
458:       [0, '#0a0d0f'], [0.55, '#0d1114'], [1, '#171c20'],
459:     ]);
460:     ctx.fillStyle = cavity;
461:     ctx.beginPath();
462:     ctx.ellipse(CX, CY + 28, 196, 168, 0, 0, TAU);
463:     ctx.fill();
464:     ctx.strokeStyle = 'rgba(180,195,205,0.12)';
465:     ctx.lineWidth = 3;
466:     ctx.stroke();
467: 
468:     // oil in the sump
469:     const oilY = 715;
470:     const oil = linear(ctx, 0, oilY, 0, 790, [[0, '#3a2814'], [0.5, '#21160b'], [1, '#0b0805']]);
471:     ctx.fillStyle = oil;
472:     ctx.beginPath();
473:     ctx.moveTo(565, oilY);
474:     ctx.bezierCurveTo(640, oilY - 6 + Math.sin(this.time * 1.7) * 2, 800, oilY + 5, 872, oilY - 2);
475:     ctx.lineTo(872, 780);
476:     ctx.bezierCurveTo(800, 800, 640, 800, 565, 780);
477:     ctx.closePath();
478:     ctx.fill();
479:     ctx.strokeStyle = 'rgba(255,170,70,0.22)';
480:     ctx.lineWidth = 2;
481:     ctx.beginPath();
482:     ctx.moveTo(565, oilY);
483:     ctx.bezierCurveTo(640, oilY - 6 + Math.sin(this.time * 1.7) * 2, 800, oilY + 5, 872, oilY - 2);
484:     ctx.stroke();
485: 
486:     // crank webs + pin (behind rod, drawn first)
487:     const px = CX + CRANK_R * Math.sin(e.theta);
488:     const py = CY - CRANK_R * Math.cos(e.theta);
489:     const cwAngle = Math.atan2(py - CY, px - CX) + Math.PI;
490:     ctx.save();
491:     ctx.translate(CX + Math.cos(cwAngle) * 28, CY + Math.sin(cwAngle) * 28);
492:     ctx.rotate(cwAngle);
493:     const web = radial(ctx, -26, -26, 5, 100, [
494:       [0, '#9aa5ae'], [0.25, '#4a545c'], [0.62, '#20262b'], [0.86, '#69747d'], [1, '#0d1013'],
495:     ]);
496:     ctx.fillStyle = web;
497:     ctx.beginPath();
498:     ctx.ellipse(0, 0, 104, 74, 0, 0, TAU);
499:     ctx.fill();
500:     ctx.strokeStyle = '#07090b';
501:     ctx.lineWidth = 3;
502:     ctx.stroke();
503:     ctx.restore();
504: 
505:     // crank pin journal
506:     const pinGrad = radial(ctx, px - 6, py - 6, 2, 24, [
507:       [0, '#eef4f8'], [0.35, '#9aa6af'], [0.7, '#3c454c'], [1, '#0a0c0e'],
508:     ]);
509:     ctx.fillStyle = pinGrad;
510:     ctx.beginPath();
511:     ctx.arc(px, py, 21, 0, TAU);
512:     ctx.fill();
513:     ctx.strokeStyle = '#050708';
514:     ctx.lineWidth = 3;
515:     ctx.stroke();
516: 
517:     // spinning crank centre
518:     ctx.save();
519:     ctx.translate(CX, CY);
520:     ctx.rotate(e.theta);
521:     ctx.fillStyle = radial(ctx, -10, -10, 2, 42, [[0, '#d9e1e7'], [0.4, '#7d8992'], [1, '#161b1f']]);
522:     ctx.beginPath();
523:     ctx.arc(0, 0, 39, 0, TAU);
524:     ctx.fill();
525:     ctx.strokeStyle = '#090b0d';
526:     ctx.lineWidth = 3;
527:     ctx.stroke();
528:     ctx.fillStyle = '#11161a';
529:     for (let i = 0; i < 6; i++) {
530:       const a = (i / 6) * TAU;
531:       ctx.beginPath();
532:       ctx.arc(Math.cos(a) * 23, Math.sin(a) * 23, 4.5, 0, TAU);
533:       ctx.fill();
534:     }
535:     ctx.restore();
536: 
537:     // oil splashes
538:     if (e.omega > 5 && Math.random() < Math.min(0.5, e.omega / 90)) {
539:       this.splashes.push({
540:         x: CX + (Math.random() - 0.5) * 150,
541:         y: 716,
542:         vx: (Math.random() - 0.5) * 90,
543:         vy: -80 - Math.random() * 100,
544:         life: 0.35 + Math.random() * 0.25,
545:         max: 0.6,
546:       });
547:     }
548:     ctx.fillStyle = 'rgba(214,150,64,0.55)';
549:     for (const p of this.splashes) {
550:       ctx.beginPath();
551:       ctx.arc(p.x, p.y, 2.2, 0, TAU);
552:       ctx.fill();
553:     }
554:   }
