556:   /* ------------------------------------------------------------------ */
557:   drawBlock(ctx, e) {
558:     // main block with cast ribs
559:     const block = linear(ctx, 596, 190, 844, 552, [
560:       [0, '#0a0d10'], [0.12, '#3b444c'], [0.25, '#8b969f'], [0.4, '#4d5860'],
561:       [0.6, '#22292e'], [0.78, '#68737c'], [0.9, '#2e353b'], [1, '#090b0d'],
562:     ]);
563:     ctx.fillStyle = block;
564:     rr(ctx, 588, 184, 264, 374, 16);
565:     ctx.fill();
566:     ctx.strokeStyle = '#050708';
567:     ctx.lineWidth = 5;
568:     ctx.stroke();
569: 
570:     // side ribs
571:     ctx.strokeStyle = 'rgba(0,0,0,0.35)';
572:     ctx.lineWidth = 4;
573:     for (let i = 0; i < 4; i++) {
574:       ctx.beginPath();
575:       ctx.moveTo(600, 360 + i * 40);
576:       ctx.lineTo(620, 348 + i * 40);
577:       ctx.stroke();
578:       ctx.beginPath();
579:       ctx.moveTo(840, 360 + i * 40);
580:       ctx.lineTo(820, 348 + i * 40);
581:       ctx.stroke();
582:     }
583: 
584:     // water jacket channels
585:     const hot = clamp((e.wallC - 20) / 90, 0, 1);
586:     for (const x0 of [606, 822]) {
587:       const grad = linear(ctx, x0, 220, x0 + 12, 520, [
588:         [0, `rgba(${lerp(50, 210, hot) | 0},${lerp(150, 110, hot) | 0},${lerp(180, 60, hot) | 0},0.7)`],
589:         [1, 'rgba(20,50,60,0.5)'],
590:       ]);
591:       ctx.fillStyle = grad;
592:       rr(ctx, x0, 218, 12, 302, 6);
593:       ctx.fill();
594:       ctx.strokeStyle = 'rgba(0,0,0,0.4)';
595:       ctx.lineWidth = 1.5;
596:       ctx.stroke();
597:       // bubbles
598:       if (e.omega > 3) {
599:         const n = 4;
600:         for (let i = 0; i < n; i++) {
601:           const t = ((this.time * (0.05 + i * 0.011) + i / n) % 1);
602:           ctx.fillStyle = `rgba(190,230,240,${0.35 * (1 - t)})`;
603:           ctx.beginPath();
604:           ctx.arc(x0 + 6, 510 - t * 280, 1.6 + i * 0.4, 0, TAU);
605:           ctx.fill();
606:         }
607:       }
608:     }
609: 
610:     // cylinder bore / liner
611:     ctx.save();
612:     ctx.beginPath();
613:     ctx.rect(BORE_L, 196, BORE, 352);
614:     ctx.clip();
615:     const liner = linear(ctx, BORE_L, 0, BORE_R, 0, [
616:       [0, '#0b0e11'], [0.08, '#4f5a63'], [0.18, '#c4cdd4'], [0.26, '#7e8a93'],
617:       [0.7, '#2a3137'], [0.88, '#535e67'], [1, '#090c0e'],
618:     ]);
619:     ctx.fillStyle = liner;
620:     ctx.fillRect(BORE_L, 196, BORE, 352);
621:     // honing marks
622:     ctx.strokeStyle = 'rgba(235,242,247,0.075)';
623:     ctx.lineWidth = 1;
624:     for (let y = 200; y < 552; y += 9) {
625:       ctx.beginPath();
626:       ctx.moveTo(BORE_L, y);
627:       ctx.lineTo(BORE_R, y + 7);
628:       ctx.stroke();
629:       ctx.beginPath();
630:       ctx.moveTo(BORE_R, y);
631:       ctx.lineTo(BORE_L, y + 7);
632:       ctx.stroke();
633:     }
634:     ctx.restore();
635: 
636:     // shadow at the bottom of the bore
637:     const depth = linear(ctx, 0, 430, 0, 552, [[0, 'rgba(0,0,0,0)'], [1, 'rgba(0,0,0,0.85)']]);
638:     ctx.fillStyle = depth;
639:     ctx.fillRect(BORE_L, 430, BORE, 122);
640: 
641:     // deck + head gasket
642:     ctx.fillStyle = '#272e34';
643:     ctx.fillRect(580, 184, 280, 13);
644:     ctx.fillStyle = '#a36f38';
645:     ctx.fillRect(588, 183, 264, 3);
646:     ctx.fillStyle = 'rgba(255,255,255,0.18)';
647:     ctx.fillRect(588, 186, 264, 1.5);
648: 
649:     // block bolts
650:     for (const [x, y] of [[604, 212], [836, 212], [604, 528], [836, 528]]) bolt(ctx, x, y, 7);
651: 
652:     // engine mount + stand
653:     ctx.strokeStyle = '#101417';
654:     ctx.lineWidth = 18;
655:     ctx.beginPath();
656:     ctx.moveTo(612, 760);
657:     ctx.lineTo(570, 900);
658:     ctx.moveTo(828, 760);
659:     ctx.lineTo(870, 900);
660:     ctx.stroke();
661:     ctx.strokeStyle = 'rgba(160,175,185,0.15)';
662:     ctx.lineWidth = 2;
663:     ctx.stroke();
664:     ctx.fillStyle = '#0b0e11';
665:     ctx.fillRect(530, 894, 380, 16);
666: 
667:     // engine designation plate
668:     ctx.save();
669:     ctx.translate(720, 500);
670:     ctx.fillStyle = 'rgba(8,10,12,0.88)';
671:     rr(ctx, -58, -15, 116, 30, 4);
672:     ctx.fill();
673:     ctx.strokeStyle = 'rgba(220,190,120,0.35)';
674:     ctx.lineWidth = 1;
675:     ctx.stroke();
676:     ctx.fillStyle = '#c9ad76';
677:     ctx.font = '700 13px "Courier New", monospace';
678:     ctx.textAlign = 'center';
679:     ctx.fillText('SC-1  449cc', 0, 5);
680:     ctx.restore();
681:   }
