683:   /* ------------------------------------------------------------------ */
684:   drawReciprocating(ctx, e) {
685:     const theta = e.theta;
686:     const pin = pistonPinY(theta);
687:     const pinY = CY - pin;
688:     const crown = pinY - PISTON_CROWN_OFF;
689:     const px = CX + CRANK_R * Math.sin(theta);
690:     const py = CY - CRANK_R * Math.cos(theta);
691:     const lean = Math.asin((CRANK_R * Math.sin(theta)) / ROD);
692: 
693:     // connecting rod
694:     ctx.save();
695:     ctx.translate(px, py);
696:     ctx.rotate(-lean);
697:     const rodLen = 300;
698:     const grad = linear(ctx, -18, 0, 18, 0, [
699:       [0, '#101417'], [0.22, '#5d6871'], [0.44, '#c3ccd3'], [0.6, '#626d76'], [0.82, '#232a2f'], [1, '#090b0d'],
700:     ]);
701:     ctx.fillStyle = grad;
702:     ctx.beginPath();
703:     ctx.moveTo(-34, 0);
704:     ctx.bezierCurveTo(-20, -40, -15, -190, -13, -rodLen + 26);
705:     ctx.lineTo(13, -rodLen + 26);
706:     ctx.bezierCurveTo(15, -190, 20, -40, 34, 0);
707:     ctx.closePath();
708:     ctx.fill();
709:     ctx.strokeStyle = '#050708';
710:     ctx.lineWidth = 3;
711:     ctx.stroke();
712:     // I-beam web
713:     ctx.strokeStyle = 'rgba(240,247,252,0.28)';
714:     ctx.lineWidth = 3;
715:     ctx.beginPath();
716:     ctx.moveTo(0, -28);
717:     ctx.lineTo(0, -rodLen + 30);
718:     ctx.stroke();
719:     // small end
720:     ctx.fillStyle = radial(ctx, -5, -rodLen + 4, 2, 30, [[0, '#d6dee5'], [0.45, '#6b767f'], [1, '#111519']]);
721:     ctx.beginPath();
722:     ctx.arc(0, -rodLen + 16, 17, 0, TAU);
723:     ctx.fill();
724:     ctx.strokeStyle = '#050708';
725:     ctx.lineWidth = 2;
726:     ctx.stroke();
727:     // big end
728:     ctx.fillStyle = radial(ctx, -10, -4, 2, 46, [[0, '#c8d2d9'], [0.42, '#5b666f'], [1, '#0e1215']]);
729:     ctx.beginPath();
730:     ctx.arc(0, 0, 34, 0, TAU);
731:     ctx.fill();
732:     ctx.strokeStyle = '#050708';
733:     ctx.lineWidth = 3;
734:     ctx.stroke();
735:     ctx.fillStyle = '#0a0d0f';
736:     ctx.beginPath();
737:     ctx.arc(0, 0, 20, 0, TAU);
738:     ctx.fill();
739:     for (const bx of [-23, 23]) bolt(ctx, bx, 0, 3.4);
740:     ctx.restore();
741: 
742:     // piston (clipped to bore)
743:     ctx.save();
744:     ctx.beginPath();
745:     ctx.rect(BORE_L + 1, 198, BORE - 2, 350);
746:     ctx.clip();
747:     const pistonGrad = linear(ctx, BORE_L + 4, 0, BORE_R - 4, 0, [
748:       [0, '#14191d'], [0.12, '#7d8891'], [0.25, '#d7dfe5'], [0.34, '#9aa5ae'],
749:       [0.55, '#58626b'], [0.78, '#8e99a2'], [0.9, '#2f363c'], [1, '#0d1013'],
750:     ]);
751:     ctx.fillStyle = pistonGrad;
752:     rr(ctx, CX - PISTON_H * 0.86, crown, PISTON_H * 1.72, PISTON_H, 10);
753:     ctx.fill();
754:     ctx.strokeStyle = '#050708';
755:     ctx.lineWidth = 3;
756:     ctx.stroke();
757:     // crown highlight
758:     ctx.fillStyle = 'rgba(235,245,252,0.30)';
759:     rr(ctx, CX - 82, crown + 4, 164, 7, 3);
760:     ctx.fill();
761:     // ring grooves
762:     for (let i = 0; i < 3; i++) {
763:       const y = crown + 20 + i * 13;
764:       ctx.fillStyle = '#07090b';
