236:         dmEx = Math.min(mdot * dt, Math.max(0, equil) * 0.32);
237:         exhaustFlow = dmEx / dt;
238:       } else {
239:         const rev = orificeFlow(this.pe, p, 850, area);
240:         dmEx = -Math.min(rev * dt, Math.max(0, -equil) * 0.32);
241:       }
242:     }
