244:     // plenum mass balance (small volume -> clamp for stability)
245:     const plenumMassRate = mdotThrottle - intakeFlow;
246:     this.pm += (plenumMassRate * R * this.tAmb * dt) / this.plenumV;
247:     this.pm = clamp(this.pm, 6000, this.pAmb * 1.03);
248:     if (this.pm > this.pAmb) this.pm = this.pAmb;
249:     this.lastThrottleFlow = mdotThrottle;
250:     this.lastIntakeFlow = intakeFlow;
251:     this.lastExhaustFlow = exhaustFlow;
252:     this.meterThrottle = (this.meterThrottle || 0) + mdotThrottle * dt;
253:     this.meterIntake = (this.meterIntake || 0) + intakeFlow * dt;
254:     this.meterExhaust = (this.meterExhaust || 0) + exhaustFlow * dt;
255:     // exhaust backpressure rises with flow, slight resonance
256:     this.pe = clamp(this.pAmb + 380 + Math.abs(exhaustFlow) * 2600, this.pAmb, this.pAmb + 9000);
257: 
258:     // ---------------- mass & energy exchange ----------------
259:     let dU = 0;
260:     if (dmIn > 0) {
261:       this.mass += dmIn;
262:       this.fuel += dmIn / this.afr;
263:       dU += cp * this.tAmb * dmIn;
264:       this.intakePulse = Math.min(1, this.intakePulse + dmIn * 2400);
265:     } else if (dmIn < 0) {
266:       const f = this.mass > 1e-9 ? Math.min(1, -dmIn / this.mass) : 0;
267:       this.mass = Math.max(0, this.mass + dmIn);
268:       this.fuel *= 1 - f;
269:       dU += cp * tCyl * dmIn;
270:     }
271:     if (dmEx > 0) {
272:       const f = this.mass > 1e-9 ? Math.min(1, dmEx / this.mass) : 0;
273:       this.mass = Math.max(0, this.mass - dmEx);
274:       this.fuel *= 1 - f;
275:       dU -= cp * tCyl * dmEx;
276:       this.exhaustPulse = Math.min(1, this.exhaustPulse + dmEx * 1700);
277:     } else if (dmEx < 0) {
278:       this.mass += -dmEx;
279:       dU += cp * 900 * -dmEx;
280:     }
281: 
282:     // ---------------- ignition & combustion ----------------
283:     const sparkAngle = (360 - this.advance + 720) % 720;
284:     let sparkNow = false;
285:     if (!this.sparkFired && this.fuel > 1e-9) {
286:       let crossed = false;
287:       if (phase >= prevPhase) crossed = sparkAngle > prevPhase && sparkAngle <= phase;
288:       else crossed = sparkAngle > prevPhase || sparkAngle <= phase;
289:       // at very low cranking speed allow a small timing nudge
290:       if (crossed || (this.omega < 15 && Math.abs(phase - sparkAngle) < 1.2)) {
291:         sparkNow = true;
292:       }
293:     }
294:     if (sparkNow) {
295:       this.sparkFired = true;
296:       this.sparkPulse = 1;
297:       this.burning = true;
298:       this.burnStart = phase;
299:       this.burned = 0;
300:       this.availableFuel = Math.max(0, this.fuel);
301:       this.cycleFuel = this.availableFuel;
302:       this.knock = 0;
303:     }
304: 
305:     let qComb = 0;
306:     if (this.burning && this.availableFuel > 0) {
307:       let elapsed = phase - this.burnStart;
308:       if (elapsed < -360) elapsed += 720;
309:       if (elapsed < 0) elapsed = 0;
310:       const u = clamp(elapsed / this.burnDuration, 0, 1);
311:       const xb = u >= 1 ? 1 : 1 - Math.exp(-6.9 * Math.pow(u, 2.1));
312:       const dx = Math.max(0, xb - this.burned);
313:       if (dx > 0) {
314:         // cold combustion is incomplete and late; mixture strength matters
315:         const warm = clamp((this.wallC - 24) / 70, 0, 1);
316:         const strength = clamp((this.availableFuel / Math.max(this.mass, 1e-9)) * this.afr, 0, 1.1);
317:         const eff = (0.58 + 0.33 * warm) * clamp(strength, 0.25, 1);
318:         const dQ = this.availableFuel * dx * this.fuelLhv * eff;
319:         qComb += dQ;
320:         this.burned += dx;
321:         this.fuel = Math.max(0, this.fuel - this.availableFuel * dx);
322:         this.combustion = Math.min(1, this.combustion + dx * 2.4);
323:       }
324:       if (u >= 1) {
325:         this.burning = false;
326:         if (this.burned < 0.6) this.lastEvent = 'MISFIRE';
327:       }
328:     }
329: 
330:     // heat release raises internal energy
331:     dU += qComb;
332: 
333:     // wall heat transfer, Woschni-ish (calibrated for a small single)
334:     const area = 0.022 + this.pistonArea;
335:     const hConv = 130 + 0.00009 * p;
336:     const dQwall = hConv * area * (tCyl - (this.wallC + 273.15)) * dt;
337:     dU -= dQwall;
338: 
339:     // first law: dU = dQ - p dV  (volume work)
340:     dU -= p * geo.dV * this.omega * dt;
341:     this.temp += dU / Math.max(this.mass * cv, 1e-7);
342:     this.temp = clamp(this.temp, 250, 3400);
343: 
344:     // wall / coolant thermal inertia
345:     const qIntoWall = dQwall;
346:     const qCool = 420 * (this.wallC - (this.tCoolant - 273.15)) * (1 + 0.75 * (this.mods?.radiator || 0));
347:     this.wallC += ((qIntoWall - qCool) / 6000) * dt;
348:     this.wallC = clamp(this.wallC, 15, 190);
349:     this.oilC += ((this.wallC - this.oilC) * 0.12 - 0.015 * (this.oilC - 45)) * dt * 0.25;
