351:     this.pressure = clamp((Math.max(this.mass, 1e-7) * R * this.temp) / Math.max(V, 1e-7), 1500, 2.6e7);
352: 
353:     // ---------------- knock ----------------
354:     const loadFrac = clamp((this.pm - 28000) / 72000, 0, 1);
355:     const heatFrac = clamp((this.wallC - 80) / 55, 0, 1.4);
356:     this.knockLimit = 35 - 13 * loadFrac - 5 * heatFrac - 2.4 * clamp(this.omega / 700, 0, 1) + 3.5 * (this.mods?.ecu || 0);
357:     let knockTarget = 0;
358:     if (this.burning && this.availableFuel > 0 && qComb > 0) {
359:       const over = this.advance - this.knockLimit;
360:       if (over > 0) {
361:         const peak = clamp(p / 4.2e6, 0.15, 1.25);
362:         knockTarget = clamp(over / 11, 0, 1) * peak;
363:       }
364:     }
365:     this.knockTarget = Math.max(knockTarget, this.knockTarget * Math.exp(-dt * 1.6));
366:     this.knockMeter += (this.knockTarget - this.knockMeter) * Math.min(1, dt * 6);
367:     this.knock = this.knockMeter;
368:     if (this.knockTarget > 0.25) {
369:       this.knockEvents++;
370:       this.detonation = Math.min(1, this.knockTarget + 0.35);
371:       this.lastEvent = 'DETONATION';
372:     }
373: 
374:     // ---------------- torque ----------------
375:     this.tInd = (p - this.pAmb) * geo.dV * (1 - 0.12 * this.knockMeter);
376:     const w = this.omega;
377:     const rpmNow = (w * 60) / TAU;
378:     this.tFric = 1.35 + 0.0055 * w + 0.0000068 * w * w;
379:     if (rpmNow > 6900) this.tFric += (rpmNow - 6900) * 0.02;
380:     if (w < 0.35) this.tFric *= 1.9;
381:     this.tLoad = (this.load / 100) * (1.2 + 0.062 * w) * 1.15;
382:     this.tStarter = 0;
383:     if (this.starter && w < 72) {
384:       this.tStarter = 52 * clamp(1 - w / 78, 0, 1);
385:       this.cranking = true;
386:     } else this.cranking = false;
387: 
388:     let net = this.tInd - this.tFric - this.tLoad + this.tStarter;
389:     if (this.loading) net -= this.loading;
390:     this.tNet = net;
391:     this.omega += (net / this.inertia) * dt;
392:     if (this.omega < 0) this.omega = 0;
393:     if (this.omega < 0.4 && this.tStarter <= 0.1 && net < 0.5) this.omega = 0;
394: 
395:     this.theta += this.omega * dt;
396:     if (this.theta >= CYCLE) {
397:       this.theta -= CYCLE;
398:       this.cycleIndex++;
399:       this.sparkFired = false;
400:       this.burning = false;
401:       this.burned = 0;
402:       this.availableFuel = Math.max(0, this.fuel);
403:       this.cycleFuel = this.availableFuel;
404:       this.totalCycles++;
405:       this.knock = 0;
406:       if (this.availableFuel > 0 && this.omega > 2) {
407:         this.burnDuration = lerp(76, 56, clamp(this.omega / 550, 0, 1));
408:       }
409:     }
410: 
411:     // measured output (averaged over a few cycles for a readable gauge)
412:     const instTorque = Math.max(0, this.tInd - this.tFric);
413:     const alpha = 1 - Math.exp(-dt / 0.55);
414:     this.torqueAvg = (this.torqueAvg ?? 0) + (instTorque - (this.torqueAvg ?? 0)) * alpha;
415:     this.torque = this.torqueAvg;
416:     this.powerKW = (this.torqueAvg * this.omega) / 1000;
417:     const rpm = (this.omega * 60) / TAU;
418:     if (rpm > 400) {
419:       this.peakRpm = Math.max(this.peakRpm, rpm);
420:       this.peakTorque = Math.max(this.peakTorque, this.torqueAvg);
421:       this.peakPower = Math.max(this.peakPower, this.powerKW * 1.34102);
422:       this.running = true;
423:     }
424:     if (rpm < 120) this.running = false;
425: 
426:     // ---------------- damage ----------------
427:     this.detonation = Math.max(0, this.detonation - dt * 5);
428:     this.combustion = Math.max(0, this.combustion - dt * 5);
429:     this.sparkPulse = Math.max(0, this.sparkPulse - dt * 22);
430:     this.exhaustPulse *= Math.exp(-dt * 9);
431:     this.intakePulse *= Math.exp(-dt * 9);
432:     this.eventTimer = Math.max(0, this.eventTimer - dt);
433: 
434:     const dmgScale = 1 - 0.55 * (this.mods?.forged || 0);
435:     if (rpm > 7250) {
436:       this.overRev = Math.min(1, this.overRev + dt * 2);
437:       this.health -= ((rpm - 7250) / 800) * 1.9 * dt * dmgScale;
438:     } else {
439:       this.overRev = Math.max(0, this.overRev - dt * 3);
440:     }
441:     if (this.wallC > 116) this.health -= (this.wallC - 116) * 0.12 * dt * dmgScale;
442:     if (this.knock > 0.22) this.health -= (this.knock - 0.2) * 5.5 * dt * dmgScale;
443:     this.health = clamp(this.health, 0, 100);
444: 
445:     if (this.health <= 0) {
446:       this.omega = 0;
447:       this.stalled = true;
448:       this.running = false;
449:       this.lastEvent = 'SEIZED';
450:     }
451:     if (this.omega < 0.4 && !this.starter) this.stalled = true;
452:     if (this.omega > 8) this.stalled = false;
453:   }
